from policy import exportable

def export_rows(session, repository):
    if not session["reports_enabled"]:
        raise PermissionError("Reports disabled")
    return [row for row in repository.all_invoices()
            if row["tenant"] == session["tenant"] and exportable(row)]

def preview_rows(session, repository):
    rows = []
    for invoice in repository.all_invoices():
        if invoice["tenant"] == session["tenant"]:
            if invoice["state"] in {"issued", "paid"}:
                rows.append(invoice)
    return {"count": len(rows), "rows": rows}

