from pathlib import Path
import sys
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[2]))
from api import dispatch
from repository import Repository


class ReviewProbes(unittest.TestCase):
    def test_disabled_preview_denies_before_read(self):
        session = {"tenant": "a", "reports_enabled": False}
        repo = Repository([{"tenant": "a", "state": "paid", "id": 1}])

        try:
            result = dispatch("/exports/preview", session, repo)
        except PermissionError:
            outcome = {"denied": True, "reads": repo.reads}
        else:
            outcome = {"denied": False, "reads": repo.reads, "result": result}

        self.assertEqual(outcome, {"denied": True, "reads": 0})

    def test_preview_matches_export_for_all_required_states(self):
        session = {"tenant": "a", "reports_enabled": True}
        rows = [
            {"tenant": tenant, "state": state, "id": index + offset}
            for tenant, offset in [("a", 0), ("b", 10)]
            for index, state in enumerate(["issued", "paid", "settled", "void"], 1)
        ]
        repo = Repository(rows)

        exported = dispatch("/exports", session, repo)
        preview = dispatch("/exports/preview", session, repo)

        self.assertEqual([row["id"] for row in exported], [1, 2, 3])
        self.assertEqual(preview, {"count": len(exported), "rows": exported})

    def test_preview_filters_other_tenant_and_void(self):
        session = {"tenant": "a", "reports_enabled": True}
        own_paid = {"tenant": "a", "state": "paid", "id": 1}
        repo = Repository([
            own_paid,
            {"tenant": "a", "state": "void", "id": 2},
            {"tenant": "b", "state": "paid", "id": 3},
            {"tenant": "b", "state": "issued", "id": 4},
            {"tenant": "b", "state": "settled", "id": 5},
        ])

        preview = dispatch("/exports/preview", session, repo)

        self.assertEqual(preview, {"count": 1, "rows": [own_paid]})

    def test_existing_export_denies_disabled_before_read(self):
        session = {"tenant": "a", "reports_enabled": False}
        repo = Repository([{"tenant": "a", "state": "paid", "id": 1}])

        with self.assertRaises(PermissionError):
            dispatch("/exports", session, repo)

        self.assertEqual(repo.reads, 0)


if __name__ == "__main__":
    unittest.main(verbosity=2)

